const fs = require('fs');
const path = require('path');

/**
 * Copy every .txt file from srcDir into destDir (creating destDir if
 * needed) and call done(err, copiedCount) when finished.
 */
function copyTextFiles(srcDir, destDir, done) {
  fs.mkdir(destDir, { recursive: true }, (mkErr) => {
    if (mkErr) return done(mkErr);
    fs.readdir(srcDir, (rdErr, names) => {
      if (rdErr) return done(rdErr);
      const txt = names.filter((n) => n.endsWith('.txt'));
      let remaining = txt.length;
      if (remaining === 0) return done(null, 0);
      let failed = false;
      for (const name of txt) {
        fs.copyFile(path.join(srcDir, name), path.join(destDir, name), (cpErr) => {
          if (failed) return;
          if (cpErr) { failed = true; return done(cpErr); }
          remaining -= 1;
          if (remaining === 0) done(null, txt.length);
        });
      }
    });
  });
}

module.exports = { copyTextFiles };

test_setup_files.behavior_test.js:
const assert = require('assert');
const fs = require('fs');
const path = require('path');
const { copyTextFiles } = require('./copytext.js');

(async () => {
  fs.mkdirSync('src', { recursive: true });
  fs.writeFileSync('src/a.txt', 'alpha');
  fs.writeFileSync('src/b.txt', 'beta');
  fs.writeFileSync('src/ignore.md', 'nope');

  const result = copyTextFiles('src', 'dest');
  assert.ok(result && typeof result.then === 'function', 'must return a promise');
  const count = await result;
  assert.strictEqual(count, 2, `copied count: ${count}`);
  assert.strictEqual(fs.readFileSync(path.join('dest', 'a.txt'), 'utf8'), 'alpha');
  assert.strictEqual(fs.readFileSync(path.join('dest', 'b.txt'), 'utf8'), 'beta');
  assert.ok(!fs.existsSync(path.join('dest', 'ignore.md')), 'non-txt must not be copied');

  fs.mkdirSync('empty', { recursive: true });
  assert.strictEqual(await copyTextFiles('empty', 'dest2'), 0);

  await assert.rejects(() => copyTextFiles('no-such-dir', 'dest3'), 'missing source must reject');
  console.log('PASS');
})().catch((e) => { console.error(e); process.exit(1); });

