const fsp = require('fs').promises;
const path = require('path');

/**
 * Copy every .txt file from srcDir into destDir (creating destDir if
 * needed). Resolves to the number of files copied.
 */
async function copyTextFiles(srcDir, destDir) {
  await fsp.mkdir(destDir, { recursive: true });
  const names = await fsp.readdir(srcDir);
  const txt = names.filter((n) => n.endsWith('.txt'));
  for (const name of txt) {
    await fsp.copyFile(path.join(srcDir, name), path.join(destDir, name));
  }
  return txt.length;
}

module.exports = { copyTextFiles };

